using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
[InitializeOnLoad]public static class GridShiftV6Checks {
 static GridShiftV6Checks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V6Sim",false)){SessionState.SetBool("V6Sim",false);new GameObject("DeliveryIntegrationChecks").AddComponent<GridShiftDeliveryChecks>();}};}
 public static void SimBatch(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");foreach(var w in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;foreach(var c in Object.FindObjectsByType<Camera>(FindObjectsSortMode.None))c.enabled=false;DeliverySaveStore.OverridePath=Path.GetFullPath("v6-simulation-save.json");SessionState.SetBool("V6Sim",true);EditorApplication.isPlaying=true;}
 public static void Structure(){var report=new StringBuilder();try{foreach(string name in new[]{"SampleScene","Office","MainMenu"}){EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");foreach(var root in UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)>0)throw new Exception("Script ausente "+name+"/"+t.name);report.AppendLine("PASS "+name+" sem scripts ausentes");}
  EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");var manager=Object.FindFirstObjectByType<DeliveryManager>();if(manager==null||manager.points.Count(p=>p.Valid)<2)throw new Exception("Sem catálogo válido");var ids=new HashSet<string>();foreach(var p in manager.points){if(!ids.Add(p.id))throw new Exception("ID de ponto duplicado");if(!p.Valid)continue;var a=p.route.pontos[p.segment].position;var b=p.route.pontos[p.segment+1].position;var direction=(b-a).normalized;float distance=Vector3.Dot(p.Stop-a,direction);if(distance<0||distance>Vector3.Distance(a,b)||Vector3.Distance(a+direction*distance,p.Stop)>.02f)throw new Exception("Parada fora da faixa");if(p.route.GetParada(out var line,out _)&&Vector3.Dot(line-p.Stop,direction)<11.9f)throw new Exception("Parada perto da faixa de pedestres");}
  report.AppendLine("PASS "+manager.points.Count(p=>p.Valid)+" locais válidos, IDs exclusivos e paradas projetadas na faixa antes do cruzamento");if(EditorBuildSettings.scenes.First(s=>s.enabled).path!="Assets/Scenes/MainMenu.unity")throw new Exception("Cena inicial incorreta");report.AppendLine("PASS MainMenu inicial; cenas do jogo preservadas");report.AppendLine("RESULT SUCCESS");File.WriteAllText("v6-structure.txt",report.ToString());EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText("v6-structure.txt",report+"\nFAIL "+e);EditorApplication.Exit(1);}}
}
public sealed class GridShiftDeliveryChecks:MonoBehaviour {
 readonly StringBuilder report=new StringBuilder();readonly List<string> errors=new List<string>();DeliveryManager manager;float probeAt;readonly HashSet<TrafficCar.StopReason> observed=new HashSet<TrafficCar.StopReason>();
 void Check(bool ok,string text){if(!ok)throw new Exception(text);report.AppendLine("PASS "+text);File.WriteAllText("v6-sim-progress.txt",report.ToString());}
 void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(text);}
 void Loaded(UnityEngine.SceneManagement.Scene scene,UnityEngine.SceneManagement.LoadSceneMode mode){foreach(var root in scene.GetRootGameObjects()){foreach(var w in root.GetComponentsInChildren<ClimaReal>(true))w.enabled=false;foreach(var c in root.GetComponentsInChildren<Camera>(true))c.enabled=false;}}
 IEnumerator Start(){DeliverySaveStore.OverridePath=Path.GetFullPath("v6-simulation-save.json");Application.runInBackground=true;Time.timeScale=5;QualitySettings.vSyncCount=0;Application.targetFrameRate=90;Application.logMessageReceived+=Log;UnityEngine.SceneManagement.SceneManager.sceneLoaded+=Loaded;
  var routines=new Stack<IEnumerator>();routines.Push(Run());bool success=true;while(routines.Count>0){object value=null;bool more;try{more=routines.Peek().MoveNext();if(more)value=routines.Peek().Current;}catch(Exception e){success=false;report.AppendLine("FAIL "+e);break;}if(!more){routines.Pop();continue;}if(value is IEnumerator nested&&!(value is CustomYieldInstruction)){routines.Push(nested);continue;}yield return value;}
  report.AppendLine("Estados de segurança observados: "+string.Join(", ",observed));report.AppendLine("Erros: "+string.Join("; ",errors));success&=errors.Count==0;report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("v6-simulation.txt",report.ToString());Application.logMessageReceived-=Log;UnityEngine.SceneManagement.SceneManager.sceneLoaded-=Loaded;Time.timeScale=1;EditorApplication.Exit(success?0:1);
 }
 IEnumerator Until(Func<bool> test,float simulatedSeconds,string label){float end=Time.time+simulatedSeconds;while(!test()&&Time.time<end)yield return null;if(!test())throw new Exception("Timeout "+label);}
 DeliveryPoint Nearby(CompanyVehicle vehicle){return manager.points.Where(p=>p.Valid&&DeliveryRouting.Find(vehicle.driver.RotaAtual,p.route,DeliveryRouting.Behind(vehicle.driver,p))!=null).OrderBy(p=>{var path=DeliveryRouting.Find(vehicle.driver.RotaAtual,p.route,DeliveryRouting.Behind(vehicle.driver,p));return path.Sum(DeliveryRouting.Length);}).First();}
 DeliveryOrder Create(float kg,CompanyVehicle vehicle,string request=null){var pickup=Nearby(vehicle);var destination=manager.points.Where(p=>p.Valid&&p!=pickup&&DeliveryRouting.Find(pickup.route,p.route)!=null).OrderBy(p=>DeliveryRouting.Find(pickup.route,p.route).Sum(DeliveryRouting.Length)).First();bool ok=manager.TryCreate(new DeliveryRequest{requestId=request??Guid.NewGuid().ToString("N"),goods="Teste físico "+kg+" kg",weightKg=kg,pickupId=pickup.id,destinationId=destination.id},out var order,out var error);Check(ok,"criar pedido "+kg+" kg: "+error);return order;}
 void Update(){if(manager==null)return;foreach(var v in manager.fleet)if(v!=null)observed.Add(v.driver.MotivoParada);if(Time.time<probeAt)return;probeAt=Time.time+20;File.WriteAllLines("v6-fleet-trace.txt",manager.fleet.Where(v=>v!=null).Select(v=>v.id+" "+v.state+" pos="+v.transform.position+" speed="+v.driver.VelocidadeAtual+" route="+v.driver.RotaAtual?.name+" wp="+v.driver.NextPoint+" target="+v.Target?.id+" targetPos="+v.Target?.Stop+" reason="+v.driver.MotivoParada));}
 IEnumerator Run(){yield return new WaitForSeconds(5);manager=DeliveryManager.Instance;Check(manager!=null,"gerenciador de entregas instalado na cidade");foreach(var p in Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None))p.BlockControls(true);yield return Until(()=>manager.fleet.Count==3,30,"frota adotada");Check(manager.fleet.All(v=>manager.traffic.Vehicles.Contains(v.driver)),"frota reaproveita três veículos do tráfego, sem instanciar novos");var cars=manager.fleet.Where(v=>v.kind==FleetKind.Car).ToArray();var truck=manager.fleet.First(v=>v.kind==FleetKind.Truck);Check(cars.Length==2&&truck.capacityKg>=2000,"dois carros e caminhão com capacidade configurada");
  var invalid=new DeliveryRequest{requestId="invalid",goods="Inválido",weightKg=-1,pickupId=manager.points[0].id,destinationId=manager.points[1].id};Check(!manager.TryCreate(invalid,out _,out _),"peso negativo recusado");invalid.weightKg=float.NaN;Check(!manager.TryCreate(invalid,out _,out _),"NaN recusado");invalid.weightKg=5;invalid.destinationId="fora-do-mapa";Check(!manager.TryCreate(invalid,out _,out _),"destino inexistente recusado");
  string request=Guid.NewGuid().ToString("N");var small=Create(5,cars[0],request);int count=manager.orders.Count;Check(manager.TryCreate(new DeliveryRequest{requestId=request},out var duplicate,out _)&&duplicate==small&&manager.orders.Count==count,"reenvio idempotente não duplica pedido");var medium=Create(50,cars[1]);var heavy=Create(500,truck);Check(!cars[0].Assign(heavy),"atribuição acima da capacidade recusada");manager.Dispatch();yield return null;Check(manager.fleet.First(v=>v.id==small.vehicleId).kind==FleetKind.Car&&manager.fleet.First(v=>v.id==medium.vehicleId).kind==FleetKind.Car&&heavy.vehicleId==truck.id,"5 e 50 kg usam carros; 500 kg usa caminhão");
  var overweight=Create(3000,truck);manager.Dispatch();Check(overweight.status==DeliveryStatus.WaitingVehicle&&string.IsNullOrEmpty(overweight.vehicleId),"3000 kg aguardam capacidade disponível");manager.Select(heavy.id);yield return null;Check(manager.GetComponent<DeliveryPresentation>().transform.Find("DestinationMap")!=null,"destino recebe marcador no minimapa");var assigned=manager.fleet.First(v=>v.id==heavy.vehicleId);var map=manager.transform.Find("FleetMap_"+assigned.id);Check(map!=null&&Vector3.Distance(map.position,assigned.transform.position+Vector3.up*22)<.3f,"marcador de veículo acompanha posição real");
  var world=WorldSession.Instance;var cityPlayer=Object.FindFirstObjectByType<PlayerMovement>();float clock=world.ClockTime;var traffic=manager.traffic;int trafficId=traffic.GetInstanceID(),managerId=manager.GetInstanceID();var truckPosition=truck.transform.position;world.RequestTransition("Office",cityPlayer.transform);yield return Until(()=>!world.Busy,100,"entrada Office");yield return new WaitForSeconds(25);Check(DeliveryManager.Instance.GetInstanceID()==managerId&&traffic.GetInstanceID()==trafficId,"Office preserva gerenciadores, pedidos e veículos");Check(world.ClockTime!=clock&&Vector3.Distance(truckPosition,truck.transform.position)>.5f,"relógio e caminhão continuam enquanto o jogador está no Office");var officePlayer=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="Office");world.RequestTransition("SampleScene",officePlayer.transform);yield return Until(()=>!world.Busy,100,"retorno cidade");Check(manager.orders.Count==4&&manager.fleet.Count==3,"sem pedidos ou frota duplicados ao voltar");
  yield return Until(()=>small.status==DeliveryStatus.Completed&&medium.status==DeliveryStatus.Completed&&heavy.status==DeliveryStatus.Completed,1800,"três entregas físicas concluídas");Check(manager.fleet.All(v=>v.Order==null&&v.Available),"coleta, transporte e descarga liberam a frota");Check(small.travelledMeters>5&&medium.travelledMeters>5&&heavy.travelledMeters>5,"pedidos percorreram metros reais sem teletransporte");float expected=small.reward+medium.reward+heavy.reward;Check(Mathf.Abs(manager.Money-expected)<.02f,"dinheiro atualizado pelas três conclusões reais");manager.Complete(heavy);Check(Mathf.Abs(manager.Money-expected)<.02f,"conclusão repetida não paga novamente");yield return new WaitForSeconds(2);Check(!manager.transform.Find("SelectedDestination").gameObject.activeSelf,"marcador 3D removido após animação de conclusão");Check(manager.GetComponent<DeliveryPersistence>().Save()&&DeliverySaveStore.Read(out var save)&&save.orders.Count==4&&Mathf.Abs(save.money-expected)<.02f,"salvamento real contém histórico, fila e dinheiro");
 }
}
